using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Collect all errors and warnings
var errors = new List<(string file, int line, int col, string code, string message, string project)>();
var warnings = new List<(string file, int line, int col, string code, string message, string project)>();

void Visit(BaseNode node, string currentProject = "")
{
    if (node is Project p) currentProject = p.ProjectFile ?? currentProject;
    if (node is Error e)
        errors.Add((e.File ?? "", e.LineNumber, e.ColumnNumber, e.Code ?? "", e.Text ?? "", currentProject));
    if (node is Warning w)
        warnings.Add((w.File ?? "", w.LineNumber, w.ColumnNumber, w.Code ?? "", w.Text ?? "", currentProject));
