        Console.WriteLine($"{new string(' ', depth*2)}{(succeeded ? "✓" : "✗")} {proj.Name} ({proj.ProjectFile})");
    }
    if (node is TreeNode tn2)
        foreach (var child in tn2.Children.OfType<BaseNode>())
            VisitProjects(child, node is Project ? depth + 1 : depth);
}
VisitProjects(build);
