using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Show all projects and their status
Console.WriteLine("=== ALL PROJECTS IN BUILD ===");
void VisitAll(BaseNode node, int depth = 0)
{
    if (node is Project proj)
    {
        bool haserr = false;
        void CheckErr(BaseNode n) {
            if (n is Error) haserr = true;
            if (n is TreeNode t) foreach (var c in t.Children.OfType<BaseNode>()) CheckErr(c);
        }
        CheckErr(proj);
        Console.WriteLine($"{(haserr ? "✗" : "✓")} {proj.Name} [{proj.TargetFramework}] ({proj.ProjectFile})");
    }
    if (node is TreeNode tn)
        foreach (var child in tn.Children.OfType<BaseNode>())
            VisitAll(child, node is Project ? depth + 1 : depth);
}
VisitAll(build);

