void FindErrors(BaseNode node) {
    if (node is Error e) errors.Add(e);
    if (node is TreeNode tn) foreach (var c in tn.Children.OfType<BaseNode>()) FindErrors(c);
}
FindErrors(build);
foreach (var e in errors)
    Console.WriteLine($"  {e.Code}: {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Text}");

// Try to find package references in the project
Console.WriteLine("\n=== MESSAGES WITH 'package' or 'Newtonsoft' ===");
void FindMessages(BaseNode node) {
    if (node is Message m && (m.Text?.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) == true 
        || m.Text?.Contains("PackageReference", StringComparison.OrdinalIgnoreCase) == true))
        Console.WriteLine($"  {m.Text?.Substring(0, Math.Min(200, m.Text.Length))}");
    if (node is TreeNode tn) foreach (var c in tn.Children.OfType<BaseNode>()) FindMessages(c);
}
FindMessages(build);
